import { readFileSync } from "node:fs";

import { sample, uniqueName, expect, test } from "../../fixtures";

test("audit events are listed oldest first with actor and action", { tag: "@AUD-01" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const created = await member.post("/api/vendors", {
    data: {
      name: uniqueName("Audit Vendor"),
      category: "services",
      contact_email: `audit.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
    },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as { id: string };

  const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.txt", mimeType: "text/plain", buffer: readFileSync(sample("w9.txt")) },
    },
  });
  expect(upload.status(), await upload.text()).toBe(201);

  // Act & Assert: extraction runs in the background, so poll until its event lands.
  const expectedActions = ["vendor.created", "document.uploaded", "document.extracted"];
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/audit`);
        expect(res.status(), await res.text()).toBe(200);
        const body = (await res.json()) as { items: { action: string }[] };
        return body.items.map((e) => e.action);
      },
      { timeout: 30_000 },
    )
    .toEqual(expectedActions);

  const finalRes = await member.get(`/api/vendors/${vendor.id}/audit`);
  expect(finalRes.status(), await finalRes.text()).toBe(200);
  const trail = (await finalRes.json()) as {
    items: { action: string; at: string; actor: { email: string; name: string; id: string } }[];
  };
  expect(trail.items.map((e) => e.action)).toEqual(expectedActions);
  for (const event of trail.items) {
    expect(event.actor.email).toBe("member@northwind.test");
    expect(event.at).toBeTruthy();
    expect(Number.isNaN(Date.parse(event.at))).toBe(false);
  }
});
